          cover: "https://lh3.googleusercontent.com/aida-public/AB6AXuAitfAbXITURqZx50bompkS7T3rl0jwMvu9z-wlbixqgiIX86Aad2RaMfHs5IOq2acT9f1gnfW4H4Z9QBR-wdzMWyIpvOo-PpN5oRy-nqBmeb0lV2md45ekg4Yspmu-OMQJweX9sHau62TVg9-Yw7eG7IhaE0GQpSj9KAvIoGxJjl8FDGcZKHW5Kz09pYUoMdkVCpACDKrDQvYrL9KuFXGm2KhiI1aB76DCGdQ-GoTk6P8pee3Q2vg3",
          actionText: "Pinjam / Reservasi",
          actionType: "primary"
        }
      ]
    };

    const categoryTitles = {
      'semua': "Koleksi Pilihan Pustakawan",
      'keahlian': "Buku Program Keahlian Kejuruan",
      'mapel': "Buku Mata Pelajaran Umum",
      'fiksi': "Koleksi Cerita Fiksi & Sastra",
      'dongeng': "Koleksi Cerita Dongeng & Rakyat",
      'lainnya': "Koleksi Referensi & Buku Lain-lain"
    };

    const container = document.getElementById('bookCatalogContainer');
    const titleEl = document.getElementById('collectionSectionTitle');
    const subtitleEl = document.getElementById('collectionSubtitle');
    const countStatusEl = document.getElementById('bookCountStatus');

    function renderBooks(category) {
      const items = booksDatabase[category] || [];
      titleEl.textContent = categoryTitles[category] || "Daftar Koleksi Buku";
      subtitleEl.textContent = `Menampilkan ${items.length} dari ${category === 'semua' ? '600' : (items.length * 25)}`;
      countStatusEl.textContent = `${items.length} Judul Ditampilkan`;

      let html = '';
      items.forEach(book => {
        let badgePill = '';
        if (book.statusType === 'available') {
          badgePill = `<span class="px-2 py-0.5 rounded bg-tertiary-container text-on-tertiary-container text-[11px] font-label-sm font-semibold flex items-center gap-0.5"><span class="material-symbols-outlined text-[12px]">check_circle</span>${book.status}</span>`;
        } else if (book.statusType === 'queued') {
          badgePill = `<span class="px-2 py-0.5 rounded bg-secondary-fixed text-on-secondary-fixed-variant text-[11px] font-label-sm font-semibold flex items-center gap-0.5"><span class="material-symbols-outlined text-[12px]">schedule</span>${book.status}</span>`;
        } else if (book.statusType === 'hybrid') {
          badgePill = `<span class="px-2 py-0.5 rounded bg-primary-fixed text-on-primary-fixed font-label-sm text-[11px] font-semibold flex items-center gap-0.5"><span class="material-symbols-outlined text-[12px]">auto_stories</span>Hybrid: ${book.status}</span>`;
        } else if (book.statusType === 'onsite') {
          badgePill = `<span class="px-2 py-0.5 rounded bg-surface-container-highest text-on-surface-variant text-[11px] font-label-sm font-semibold flex items-center gap-0.5"><span class="material-symbols-outlined text-[12px]">lock</span>${book.status}</span>`;
        }

        let actionArea = '';
        if (book.actionType === 'primary') {
          actionArea = `
            <div class="flex items-center gap-space-xs pt-1">
              <button class="flex-1 py-2 px-3 rounded-lg bg-primary-container text-on-primary font-label-md text-label-md flex items-center justify-center gap-1.5 active:scale-98 transition-transform shadow-xs">
                <span class="material-symbols-outlined text-[18px]">bookmark_add</span>
                <span>${book.actionText}</span>
              </button>
              <button aria-label="Simpan" class="w-10 h-9 rounded-lg bg-surface-container hover:bg-surface-container-high text-on-surface flex items-center justify-center transition-colors">
                <span class="material-symbols-outlined text-[20px]">favorite_border</span>
              </button>
              <button aria-label="Bagikan" class="w-10 h-9 rounded-lg bg-surface-container hover:bg-surface-container-high text-on-surface flex items-center justify-center transition-colors">
                <span class="material-symbols-outlined text-[20px]">share</span>
              </button>
            </div>`;
        } else if (book.actionType === 'queue') {
          actionArea = `
            <div class="flex items-center gap-space-xs pt-1">
              <button class="flex-1 py-2 px-3 rounded-lg bg-surface-container-high text-on-surface font-label-md text-label-md flex items-center justify-center gap-1.5 hover:bg-surface-container-highest active:scale-98 transition-transform">
                <span class="material-symbols-outlined text-[18px]">alarm_on</span>
                <span>${book.actionText}</span>
              </button>
              <button aria-label="Simpan" class="w-10 h-9 rounded-lg bg-surface-container hover:bg-surface-container-high text-on-surface flex items-center justify-center transition-colors">
                <span class="material-symbols-outlined text-[20px]">favorite_border</span>
              </button>
            </div>`;
        } else if (book.actionType === 'hybrid') {
          actionArea = `
            <div class="grid grid-cols-2 gap-space-xs pt-1">
              <button class="py-2 px-2 rounded-lg bg-secondary-container text-on-secondary-container font-label-md text-label-md flex items-center justify-center gap-1 active:scale-98 transition-transform shadow-xs">
                <span class="material-symbols-outlined text-[16px]">menu_book</span>
                <span class="truncate">Baca E-Book</span>
              </button>
              <button class="py-2 px-2 rounded-lg bg-surface-container-high text-on-surface font-label-md text-label-md flex items-center justify-center gap-1 hover:bg-surface-container-highest active:scale-98 transition-transform">
                <span class="material-symbols-outlined text-[16px]">location_on</span>
                <span class="truncate">Cek Posisi Rak</span>
              </button>
            </div>`;
        } else if (book.actionType === 'onsite') {
          actionArea = `
            <div class="flex items-center gap-space-xs pt-1">
              <button class="flex-1 py-2 px-3 rounded-lg bg-surface-container-high text-on-surface font-label-md text-label-md flex items-center justify-center gap-1.5 hover:bg-surface-container-highest active:scale-98 transition-transform">
                <span class="material-symbols-outlined text-[18px]">map</span>
                <span>${book.actionText}</span>
              </button>
              <button aria-label="Simpan" class="w-10 h-9 rounded-lg bg-surface-container hover:bg-surface-container-high text-on-surface flex items-center justify-center transition-colors">
                <span class="material-symbols-outlined text-[20px]">bookmark_border</span>
              </button>
            </div>`;
        }

        html += `
          <article class="flex flex-col bg-surface-container-lowest rounded-xl p-space-md shadow-sm space-y-space-sm transition-all hover:shadow-md animate-fade-in">
            <div class="flex gap-space-md">
              <div class="w-24 h-36 flex-shrink-0 rounded-lg overflow-hidden bg-surface-container relative shadow-xs">
                <img class="w-full h-full object-cover" src="${book.cover}" alt="${book.title}">
                <div class="absolute top-1 left-1 px-1.5 py-0.5 rounded bg-primary-container/90 text-on-primary text-[10px] font-label-sm font-medium">
                  ${book.badge}
                </div>
              </div>
              <div class="flex-1 min-w-0 flex flex-col justify-between">
                <div class="space-y-1">
                  <div class="flex flex-wrap items-center gap-1">
                    <span class="px-2 py-0.5 rounded bg-surface-container-high text-on-surface-variant text-[11px] font-label-sm">${book.type}</span>
                    ${badgePill}
                  </div>
                  <h3 class="font-headline-sm text-headline-sm text-primary text-[16px] leading-snug line-clamp-2">
                    ${book.title}
                  </h3>
                  <p class="font-body-sm text-body-sm text-on-surface-variant line-clamp-1">
                    ${book.author}
                  </p>
                </div>
                <div class="pt-2 flex items-center justify-between text-on-surface-variant font-label-sm text-label-sm">
                  <div class="flex items-center gap-1 bg-surface-container-low px-2 py-1 rounded">
                    <span class="material-symbols-outlined text-[14px] text-outline">shelves</span>
                    <span>${book.shelf}</span>
                    <span class="text-outline">|</span>
                    <span class="font-semibold text-primary">${book.ddc}</span>
                  </div>
                </div>
              </div>
            </div>
            ${actionArea}
          </article>
        `;
      });

      container.innerHTML = html;
    }

    // Category Filter Chips Highlighting & Filtering Event
    const chips = document.querySelectorAll('.filter-chip');
    chips.forEach(chip => {
      chip.addEventListener('click', function() {
        const cat = this.getAttribute('data-category');
        chips.forEach(c => {
          c.className = "filter-chip flex-shrink-0 px-3.5 py-1.5 rounded-full font-label-md text-label-md hover:bg-surface-container-high transition-all bg-surface-container-lowest text-on-surface-variant border border-outline-variant/40";
        });
        this.className = "filter-chip flex-shrink-0 px-3.5 py-1.5 rounded-full font-label-md text-label-md transition-all bg-primary-container text-on-primary shadow-xs ring-1 ring-primary/20";
        renderBooks(cat);
      });
    });

    // Render initial collection (Semua Koleksi)
    renderBooks('semua');

    // Search Input Clear Button
    const searchInput = document.getElementById('searchInput');
    const clearBtn = document.getElementById('clearSearchBtn');

    if (searchInput && clearBtn) {
      searchInput.addEventListener('input', function() {
        if (this.value.length > 0) {
          clearBtn.classList.remove('hidden');
        } else {
          clearBtn.classList.add('hidden');
        }
      });
      clearBtn.addEventListener('click', function() {
        searchInput.value = '';
        clearBtn.classList.add('hidden');
        searchInput.focus();
      });
    }
  })();
</script>
</body></html>